useEffect(() => {
  const savedUser = localStorage.getItem("user");
  const savedToken = localStorage.getItem("token");

  console.log("🔎 [AuthContext] Loaded user from storage:", savedUser);
  console.log("🔎 [AuthContext] Loaded token from storage:", savedToken);

  if (savedUser && savedToken) {
    try {
      const decoded = jwtDecode(savedToken);
      console.log("🔎 [AuthContext] Decoded token:", decoded);

      if (decoded.exp * 1000 > Date.now()) {
        setUser(JSON.parse(savedUser));
        setToken(savedToken);
      } else {
        console.warn("⚠️ [AuthContext] Token expired, clearing storage");
        localStorage.removeItem("user");
        localStorage.removeItem("token");
      }
    } catch (err) {
      console.error("❌ [AuthContext] Invalid token:", err);
      localStorage.removeItem("user");
      localStorage.removeItem("token");
    }
  }
}, []);
